def invert_tree_brute(root):
    if root is None:
        return None
    nodes = []
    def collect(node):
        if node:
            nodes.append(node)
            collect(node.left)
            collect(node.right)
    collect(root)
    for node in nodes:
        node.left, node.right = node.right, node.left      # swap in a SEPARATE pass
    return root

